static LINES:Mutex<Vec<String>>=Mutex::new(Vec::new());static IDLE:AtomicBool=AtomicBool::new(true);static NOW:AtomicI64=AtomicI64::new(1);static DEVICE_AVAILABLE:AtomicBool=AtomicBool::new(true);
