mod diag_pages{use core::fmt;pub struct Line{b:[u8;192],n:usize}impl Line{pub const fn new()->Self{Self{b:[0;192],n:0}}pub fn as_str(&self)->&str{core::str::from_utf8(&self.b[..self.n]).unwrap()}}impl fmt::Write for Line{fn write_str(&mut self,s:&str)->fmt::Result{if self.n+s.len()>192{return Err(fmt::Error)}self.b[self.n..self.n+s.len()].copy_from_slice(s.as_bytes());self.n+=s.len();Ok(())}}}
