mod core_admission{pub struct DiagnosticPermit;}
mod core_coordinator{use crate::core_admission::DiagnosticPermit;pub struct Coordinator{pub held:bool,pub quarantine:bool,pub releases:u32}impl Coordinator{pub const fn new()->Self{Self{held:false,quarantine:false,releases:0}}pub fn diagnostic(&mut self)->Result<DiagnosticPermit,()>{if self.held||self.quarantine{return Err(())}self.held=true;Ok(DiagnosticPermit)}pub fn unissued_diagnostic_finished(&mut self,_:DiagnosticPermit)->Result<(),()>{assert!(self.held);self.held=false;self.releases+=1;Ok(())}pub fn quarantine(&mut self){self.quarantine=true;}}pub static CONTROL:std::sync::Mutex<Coordinator>=std::sync::Mutex::new(Coordinator::new());}
mod device{
 use std::{marker::PhantomData,sync::{Mutex,MutexGuard}};
 pub mod drivers{pub mod fpga{#[derive(Clone,Copy)]pub enum FpgaSpiWordSize{Bits32}pub const MAX_SPI_READ_CLOCK:u32=16000000;pub struct SpiCommand{pub word_size:FpgaSpiWordSize,pub byte_swap:bool,pub increment_address:bool}pub struct Fpga{pub words:[u32;40],pub epoch:u32,pub reads:u32,pub fail_at:u32,pub captures:u32,pub fail_write:bool,pub read_delay:i64,pub writes:Vec<(u32,u32)>}impl Fpga{pub const fn new()->Self{Self{words:[0;40],epoch:1,reads:0,fail_at:0,captures:0,fail_write:false,read_delay:0,writes:Vec::new()}}pub fn program_epoch(&self)->u32{self.epoch}pub fn read_u32(&mut self,a:u32)->Result<u32,()>{crate::NOW.fetch_add(self.read_delay,crate::Ordering::Relaxed);self.reads+=1;if self.reads==self.fail_at{return Err(())}Ok(match a-0xe0000000{0=>crate::cpl1::ID,4=>crate::cpl1::SCHEMA,8=>0,0x184=>crate::cpl1::IMAGE,o@0x500..=0x59c=>self.words[(o as usize-0x500)/4],_=>panic!("address")})}pub fn spi_write(&mut self,clock:Option<u32>,cmd:SpiCommand,a:u32,b:&[u8])->Result<(),()>{assert_eq!(clock,Some(16000000));if self.fail_write{return Err(())}assert!(!cmd.byte_swap&&cmd.increment_address);assert!(matches!(cmd.word_size,FpgaSpiWordSize::Bits32));assert_eq!(a,0xe0000500);let v=u32::from_be_bytes(b.try_into().unwrap());assert_ne!(v,0);self.writes.push((a,v));self.words[0]=v;self.words[1]+=1;self.words[2]=crate::cpl1::SCHEMA;self.words[25]=3;self.captures+=1;Ok(())}}}}
 pub struct Device<'a>{pub fpga:drivers::fpga::Fpga,pub p:PhantomData<&'a ()>}
 pub static DEVICE:Mutex<Device<'static>>=Mutex::new(Device{fpga:drivers::fpga::Fpga::new(),p:PhantomData});
 impl Device<'_>{pub fn try_lock()->Option<MutexGuard<'static,Device<'static>>>{if !crate::DEVICE_AVAILABLE.load(crate::Ordering::Relaxed){None}else{DEVICE.try_lock().ok()}}}
}
#[path="../handheld/src/cpl1_usb.rs"]mod usb;
fn reset(){IDLE.store(true,Ordering::Relaxed);DEVICE_AVAILABLE.store(true,Ordering::Relaxed);NOW.store(1,Ordering::Relaxed);*core_coordinator::CONTROL.lock().unwrap()=core_coordinator::Coordinator::new();device::DEVICE.lock().unwrap().fpga=device::drivers::fpga::Fpga::new();LINES.lock().unwrap().clear();}
#[test]fn sdk_group_errors_release_and_clock_scope(){reset();for failed in [1,14,19,28,60,100,170]{device::DEVICE.lock().unwrap().fpga.reads=0;device::DEVICE.lock().unwrap().fpga.fail_at=failed;usb::command();for _ in 0..12{usb::tick();}assert!(!core_coordinator::CONTROL.lock().unwrap().held);assert!(LINES.lock().unwrap().last().unwrap().contains("Io"));}device::DEVICE.lock().unwrap().fpga.fail_at=0;}
#[test]fn sdk_quiet_reservation_timeout_and_pages(){reset();IDLE.store(false,Ordering::Relaxed);usb::command();assert_eq!(device::DEVICE.lock().unwrap().fpga.reads,0);IDLE.store(true,Ordering::Relaxed);usb::command();assert!(core_coordinator::CONTROL.lock().unwrap().held);DEVICE_AVAILABLE.store(false,Ordering::Relaxed);NOW.store(600000,Ordering::Relaxed);usb::tick();assert!(!core_coordinator::CONTROL.lock().unwrap().held);assert!(LINES.lock().unwrap().last().unwrap().contains("Timeout"));DEVICE_AVAILABLE.store(true,Ordering::Relaxed);usb::command();for _ in 0..10{usb::tick();}assert!(!core_coordinator::CONTROL.lock().unwrap().held);let r=device::DEVICE.lock().unwrap().fpga.reads;LINES.lock().unwrap().clear();for _ in 0..10{usb::command();}assert_eq!(device::DEVICE.lock().unwrap().fpga.reads,r);for (i,l) in LINES.lock().unwrap().iter().enumerate(){assert!(l.contains(&format!("page={}",i)));assert!(l.len()<=192);}usb::command();assert!(core_coordinator::CONTROL.lock().unwrap().held);for _ in 0..10{usb::tick();}for _ in 0..10{usb::command();}}

#[test]fn capture_write_error_releases_without_control_commands(){reset();device::DEVICE.lock().unwrap().fpga.fail_write=true;usb::command();assert!(!core_coordinator::CONTROL.lock().unwrap().held);assert!(LINES.lock().unwrap().last().unwrap().contains("Io"));assert_eq!(device::DEVICE.lock().unwrap().fpga.captures,0);device::DEVICE.lock().unwrap().fpga.fail_write=false;}

#[test]fn overrunning_spi_group_is_not_cached(){reset();usb::command();device::DEVICE.lock().unwrap().fpga.read_delay=40000;usb::tick();assert!(!core_coordinator::CONTROL.lock().unwrap().held);assert!(LINES.lock().unwrap().last().unwrap().contains("Timeout"));device::DEVICE.lock().unwrap().fpga.read_delay=0;}
